 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_drMgtList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const drMgtListdata = dlt_drMgtList.getRowJSON(rowIndex);
        const stdCd = drMgtListdata.stdCd;

        await scwin.searchDetail(stdCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15600.grd_drMgtList_oncellclick" });
