/**
 * @method
 * @name cmb_cb_p_group_onchange
 * @description CFI 그룹
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onchange = function (info) {
    try {
        if (cmb_cb_p_group.getValue() !== "") {
            let str_cfi = dma_drMgtDetail.get("cfiCd");
            const temp1 = ""; // str_cfi.substring(0, 1);//카테고리 cfi첫자리
            const temp2 = cmb_cb_p_group.getValue(); // 선택한 그룹
            let productDiv = "";
            let categoryDiv = "";

            // 그룹에따라 [상품구분, 카테고리] 셋팅
            productDiv = "06";
            if (temp2 === "E") {
                // 주권예탁증서
                categoryDiv = "E";
            } else if (temp2 === "D") {
                // 채무증권예탁증서
                categoryDiv = "D";
            } else if (temp2 === "R") {
                // 권리예탁증서
                categoryDiv = "R";
            }

            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "1", "");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr2, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "2", "");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr3, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "3", "");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr4, scwin.vScrenID, SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, temp2, "4", "");
            // alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): setObjectValue(label_attr1, "(" + dts_cfi_attr1.NameValue(2, "HEAD_NM") + ")");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): setObjectValue(label_attr2, "(" + dts_cfi_attr2.NameValue(2, "HEAD_NM") + ")");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): setObjectValue(label_attr3, "(" + dts_cfi_attr3.NameValue(2, "HEAD_NM") + ")");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): setObjectValue(label_attr4, "(" + dts_cfi_attr4.NameValue(2, "HEAD_NM") + ")");
        }
        scwin.changeCfi();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS15600.cmb_cb_p_group_onchange" });
    }
};

