///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setComboCode
 * @description 공통코드 조회 — 공통코드 API(commCodeValue-select)로 selectbox 데이터 설정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setComboCode = async function (){
    /**
     * CNTR_CD                  발행기관국가코드
     * NEWSTK_KIND_CD           신/구주종류(0:구주,1:1신주,2:2신주...9:9신주)
     * BAS_SECU_KIND_CD         기초증권종류(0:주식,1:채권,2:기타)
     * CURR_TP_CD               발행통화(0:기타.1:원화,2:달러,3:엔화,...9:싱가폴달러)
     * DOM_FORN_STKCERT_TP_CD   국내/해외주권 발행구분(D:국내,I:해외)
     * LIST_STAT_CD             상장여부(D:상장폐지,I:미발행,N:비상장,Y:상장,Z:기타)
     * STD_CD_APCT_TP_CD        신청인 구분(1:발행기관,2:대표주관회사,3:채권부,4:기타,5:온라인소액투자중개업자)
     */

    dma_searchCode.set("codeList", "STD_CD_APCT_TP_CD, CNTR_CD, NEWSTK_KIND_CD, BAS_SECU_KIND_CD, DOM_FORN_STKCERT_TP_CD, CURR_TP_CD, LIST_STAT_CD");

    const sbmOptions = {
        id : "sbm_searchCode",
        action : "/api/isin/common/api/commCode/commCodeValue-select",
        method : "get",
        ref : "dma_searchCode",
        target : "dlt_STD_CD_APCT_TP_CD=body.STD_CD_APCT_TP_CD,dlt_CNTR_CD=body.CNTR_CD,dlt_NEWSTK_KIND_CD=body.NEWSTK_KIND_CD,dlt_BAS_SECU_KIND_CD=body.BAS_SECU_KIND_CD,dlt_DOM_FORN_STKCERT_TP_CD=body.DOM_FORN_STKCERT_TP_CD,dlt_CURR_TP_CD=body.CURR_TP_CD,dlt_LIST_STAT_CD=body.LIST_STAT_CD",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name search
 * @description 예탁증서 표준코드관리  목록 조회한다.
 * @returns {Promise<Boolean>}
 * @hidden N
 */
scwin.search = async function() {
    if ($c.util.isEmpty(txb_pSTD_CD.getValue()) &&
        $c.util.isEmpty(txb_pISU_NM.getValue()) &&
        $c.util.isEmpty(txb_pISUR_CD.getValue()) &&
        $c.util.isEmpty(edt_pSTD_CD_GRNT_DD_SDATE.getValue()) &&
        $c.util.isEmpty(edt_pSTD_CD_GRNT_DD_EDATE.getValue())) {
        await $c.win.alert("조회 파라메터가 부족합니다");
        return;
    }

    // 검색일 체크
    if (!(await scwin.checkFromTo(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE, "발행일"))) return false;

    // 검색일 체크
    if (!(await scwin.checkFromTo(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE, "코드부여일"))) return false;

    // 데이터셋 초기화
    dma_drMgtDetail.reset();

    cmb_SECU_KIND_CD.setValue("");

    dma_search.set("stdCd", txb_pSTD_CD.getValue());
    dma_search.set("isuNm", txb_pISU_NM.getValue());
    dma_search.set("isurCd", txb_pISUR_CD.getValue());
    dma_search.set("isuDdSdate", edt_pISU_DD_SDATE.getValue());
    dma_search.set("isuDdEdate", edt_pISU_DD_EDATE.getValue());
    dma_search.set("stdCdGrntDdSdate", edt_pSTD_CD_GRNT_DD_SDATE.getValue());
    dma_search.set("stdCdGrntDdEdate", edt_pSTD_CD_GRNT_DD_EDATE.getValue());

    const sbmOptions = {
        id : "sbm_search",
        action : "/api/isin/api/stdcdMgtGrp/drMgt/drMgtList-select",
        method : "get",
        ref : "dma_search",
        target : "dlt_drMgtList=body",
        gridview : "grd_drMgtList|focus"
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    if (sbmRtn && sbmRtn.skipped) return;
    scwin.sbm_search_submitdone(sbmRtn);
};

