/**
 * @method
 * @name modify
 * @description 예탁증서 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} mflag 검증만 수행 여부(N: 검증만, Y: 저장)
 * @returns {Promise<Boolean>}
 * @hidden N
 */
scwin.modify = async function(mflag) {
    const screenProcsTpCd = "03";
    if (screenProcsTpCd === '03') {
        // 수정
        if (!$c.data.isModified(dma_drMgtDetail)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
        // 필수 입력 검증(규칙 24 — validateDataCollect)
        const isValid = await $c.validate.validateDataCollect(panel_1, {
            fields : {
                txb_STD_CD : { required : true, name : "표준코드" },
                txb_ISU_NM : { required : true, name : "한글종목명" },
                txb_ISU_ABBRV : { required : true, name : "한글종목약명" },
                txb_ISU_ENG_NM : { required : true, name : "영문종목명" },
                txb_ISU_ENG_ABBRV : { required : true, name : "영문종목약명" }
            }
        });
        if (!isValid) return false;
        // byte 길이 검사(AS-IS 규약: 한글 2byte — $c.fil.checkMaxLength 가 초과 시 알림·포커스)
        if (!$c.fil.checkMaxLength(txb_STD_CD, 12, "표준코드")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) return false;
        if (!$c.fil.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) return false;
        if (mflag === "N") return;

        dma_modify.setJSON(dma_drMgtDetail.getJSON());
        dma_modify.set("transtrEmpNo", scwin.empNo);
        dma_modify.set("empNm", scwin.empNm);

        const sbmOptions = {
            id : "sbm_modify",
            action : "/api/isin/api/stdcdMgtGrp/drMgt/drMgt-save",
            method : "post",
            ref : "dma_modify",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        if (sbmRtn && sbmRtn.skipped) return;
        await scwin.sbm_modify_submitdone(sbmRtn);
    }
};

