/**
 * @method
 * @name createStdIsuNm
 * @description 주권 종목명 생성
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.createStdIsuNm = async function() {

    dma_searchIsuNm.undo();
    dma_searchIsuNm.set("isurCd", txb_ISUR_CD.getValue());
    dma_searchIsuNm.set("stkcertKindNm", "000");

    const sbmOptions = {
        id : "sbm_getIsuNm",
        action : "/api/isin/api/stdcdMgtGrp/stkcertMgt/stkcertMgtBasNmPreferShare-select",
        method : "get",
        ref : "dma_searchIsuNm",
        target : "dma_getIsuNm=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) return;

    /*
    - 한글종목명 : 발행기관명+KDR
    - 한글종목약명 : 발행기관약명+KDR
    - 영문종목명 : 발행기관명(영)+KDR
    - 영문종목약명 : 발행기관약명(영)+KDR
     * 주권의 기준종목명 테이블에 정보가 있는 경우 그 정보를 가져와 +이후 규칙대로.
     */
    if ($c.util.isEmpty(res.responseJSON.body)) {
        await $c.win.alert("해당 주권종류 코드가 존재하지 않습니다.");
        return;
    }

/*
    // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): var A = dts_createStdCdStkInfoStdIsuNm.NameValue(1, "A");
    // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): var B = dts_createStdCdStkInfoStdIsuNm.NameValue(1, "B");
    // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): var C = dts_createStdCdStkInfoStdIsuNm.NameValue(1, "C");
    // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): var D = dts_createStdCdStkInfoStdIsuNm.NameValue(1, "D");
    // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): var E = dts_createStdCdStkInfoStdIsuNm.NameValue(1, "E"); // 기존 주권의 보통주 존재여부
 */
    let A = dma_getIsuNm.get("comNm");
    let B = dma_getIsuNm.get("comAbbrv");
    let C = dma_getIsuNm.get("comEngNm");
    let D = dma_getIsuNm.get("comEngAbbrv");
    const E = dma_getIsuNm.get(""); // 기존 주권의 보통주 존재여부 — TODO Stage2: 응답 키 미정(AS-IS NameValue(1, "E")) — API 응답 확인 후 키 지정

    A = A.replace("보통주", "").trim();
    B = B.replace("보통주", "").trim();
    C = C.replace("보통주", "").trim();
    D = D.replace("보통주", "").trim();

    if (E === "Y") {
        //     주권에존재
        txb_ISU_NM.setValue(A);
        txb_ISU_ABBRV.setValue(B);
        txb_ISU_ENG_NM.setValue(C);
        txb_ISU_ENG_ABBRV.setValue(D);
    } else {
        //     주권에미존재
        txb_ISU_NM.setValue(A + " KDR");
        txb_ISU_ABBRV.setValue(B + " KDR");
        txb_ISU_ENG_NM.setValue(C + " KDR");
        txb_ISU_ENG_ABBRV.setValue(D + " KDR");
    }
};

