/**
 * @method
 * @name sbm_searchDtl_submitdone
 * @description searchDtl 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_searchDtl_submitdone = async function(e) {

    if($c.util.isEmpty(e.responseJSON.body)){
        return;
    }else{
        cmb_LIST_STAT_CD.setValue("");
        // fn_CtrlBtn_temp("update");
        btn_modify.setDisabled(false);
        btn_delete.setDisabled(false);
        btn_file.setDisabled(false);
        btn_prcnm.setDisabled(false);

        let str_cfi_cd = "";
        str_cfi_cd = dma_drMgtDetail.get("cfiCd");

        // if(  str_cfi_cd != undefined && str_cfi_cd.length == "6"){
        //    setObjectValue(cmb_SECU_KIND_CD, str_cfi_cd.substring(5, 6)); // 4차속성 <-- CFI 4차속성 증권의 종류
        // }else{
        //    setObjectValue(cmb_SECU_KIND_CD, ""); // 4차속성 <-- CFI 4차속성 증권의 종류
        // }

        scwin.setCfiCombo(str_cfi_cd);

        if (dma_drMgtDetail.get("isurCd") === "") {
            await $c.win.alert("외국기관 코드를 찾을 수 없습니다");
        }

        let flag = false;
        // 상장 폐지일이 있으므로 상장폐지이다.
        if (dma_drMgtDetail.get("secuMktStkcertDelistDd") !== "") {
            cmb_LIST_STAT_CD.setValue("D");
            flag = true;
        }

        let flag1 = false;
        if (flag === false) {
            // 상징일 is not null 상장폐지일 null -> 상장으로 판단 2013.11.15 최진호대리님
            if (dma_drMgtDetail.get("secuMktStkcertListDd") !== "" &&
                dma_drMgtDetail.get("secuMktStkcertDelistDd") === "") {
                flag1 = true;
                btn_modify.setDisabled(true);
                btn_delete.setDisabled(true);

                cmb_LIST_STAT_CD.setValue("Y");
            } else {
                cmb_LIST_STAT_CD.setValue("N");
            }
        }

        if (flag1 === true) {
            // alert(" 상장종목은 수정할 수 없습니다. \n 공시총괄팀과 협의하시기 바랍니다.");
        }
    }
};

