/**********************************************
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
// scwin.arrPar = com.wconv.array();

/**
 * @method
 * @name getParam
 * @description 팝업 전달값(txb_param1: 표준코드/발행기관코드, txb_param2: 구분값)을 배열로 정의한다
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {*}
 * @hidden N
 */
scwin.getParam = function (arrPar) {
    // ISIN 공통 팝업(ULDINS93300 등)이 opener 의 scwin.getParam(arrPar) 을 호출해 배열을 참조로 채우는 계약 — 인자가 없으면 scwin.arrPar 사용
    const out = Array.isArray(arrPar) ? arrPar : scwin.arrPar;
    out[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드
    out[1] = txb_param2.getValue(); // 구분값
    return out;
};

/**
 * @method
 * @name changeCfi
 * @description cfi 변경 설정
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";

    let str_cfi = dma_drMgtDetail.get("cfiCd");

    let temp = cmb_cb_p_group.getValue(); // 선택된그룹

    // 카테고리셋팅
    if (temp === "") {
        cfi = "_";
    } else if (temp === "E") {
        cfi = "E";
    } else if (temp === "D") {
        cfi = "D";
    } else if (temp === "R") {
        cfi = "R";
    }

    // 그룹
    if (cmb_cb_p_group.getValue() === "") cfi += "_";
    else cfi += "D"; // cfi += cmb_cb_p_group.getValue();

    // 1차속성
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";
    else cfi += cmb_cb_p_attr_1.getValue();

    // 2차속성
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";
    else cfi += cmb_cb_p_attr_2.getValue();

    // 3차속성
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";
    else cfi += cmb_cb_p_attr_3.getValue();

    // 4차속성
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";
    else cfi += cmb_cb_p_attr_4.getValue();

    txb_CFI_CD.setValue(cfi); // cfi 설정
};

/**
 * @method
 * @name setCfiCombo
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi CFI 코드
 * @returns {void}
 * @hidden N
 */
scwin.setCfiCombo = function(str_cfi) {
    if (str_cfi === "") return;

//    $c.cm.insCfiSet(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "06", "E", "", "", "G");
//    $c.cm.insCfiSet(dts_cfi_group_1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "06", "D", "", "", "G");
//    $c.cm.insCfiSet(dts_cfi_group_2, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "06", "R", "", "", "G");

    // 하나의 데이터셋으로 합치기
//    for (var i = 2; i < dts_cfi_group_1.CountRow + 1; i++) {
//        dts_cfi_group.insertRow(); /*ORG SRC: dts_cfi_group.NameValue(dts_cfi_group.CountRow, "VALUE") = dts_cfi_group_1.NameValue(i, "VALUE");*/ X = dts_cfi_group_1.NameValue(i, "VALUE"); /*ORG SRC: dts_cfi_group.NameValue(dts_cfi_group.CountRow, "TEXT") = dts_cfi_group_1.NameValue(i, "TEXT");*/ X = dts_cfi_group_1.NameValue(i, "TEXT");
//    }
//    for (var i = 2; i < dts_cfi_group_2.CountRow + 1; i++) {
//        dts_cfi_group.insertRow(); /*ORG SRC: dts_cfi_group.NameValue(dts_cfi_group.CountRow, "VALUE") = dts_cfi_group_2.NameValue(i, "VALUE");*/ X = dts_cfi_group_2.NameValue(i, "VALUE"); /*ORG SRC: dts_cfi_group.NameValue(dts_cfi_group.CountRow, "TEXT") = dts_cfi_group_2.NameValue(i, "TEXT");*/ X = dts_cfi_group_2.NameValue(i, "TEXT");
//    }

    // DR 특수케이스
    let temp = str_cfi.substring(0, 2); // 카테고리 + 그룹
    // alert(temp);
    if (temp === "ED") {
        cmb_cb_p_group.setValue("E");
    } else if (temp === "DD") {
        cmb_cb_p_group.setValue("D");
    } else if (temp === "RD") {
        cmb_cb_p_group.setValue("R");
    }
    // setObjectValue(cmb_cb_p_group,str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name openInsPopup
 * @description ISIN 공통 팝업(/ui/ins/common) 호출 — 결과가 있으면 코드/명 컴포넌트에 반영(AS-IS $c.cm.insPopupOpen 대체)
 * @param {*} cdObj 코드 값을 받을 컴포넌트(없으면 "")
 * @param {*} nmObj 명칭 값을 받을 컴포넌트(없으면 "")
 * @param {String} screenId 팝업 화면 ID
 * @param {String} title 팝업 제목
 * @param {String} width 팝업 너비
 * @param {String} height 팝업 높이
 * @returns {Promise<*>} 팝업 반환값
 * @hidden N
 */
scwin.openInsPopup = async function (cdObj, nmObj, screenId, title, width, height) {
    const options = {
        id : screenId,
        popupName : title,
        width : parseInt(width, 10) + 10,
        height : parseInt(height, 10) + 10
    };
    // 팝업(ULDINS93300 전환본 등)은 opener 의 scwin.getParam(arrPar) 을 직접 호출해 파라미터를 받는다 — data 는 참고용
    // TODO Stage2: ISIN 공통 팝업 반환 형태 확인 — AS-IS 는 팝업이 opener 의 js_ins_popup_cd/nm 컴포넌트에 직접 값을 설정
    const rtn = await $c.win.openPopup("/ui/ins/common/" + screenId + ".xml", options, { arrPar : scwin.getParam() });
    if (!$c.util.isEmpty(rtn)) {
        if (!$c.util.isEmpty(cdObj) && !$c.util.isEmpty(rtn.cd)) cdObj.setValue(rtn.cd);
        if (!$c.util.isEmpty(nmObj) && !$c.util.isEmpty(rtn.nm)) nmObj.setValue(rtn.nm);
    }
    return rtn;
};

/**
 * @method
 * @name alertRequiredDelByWeb
 * @description 신청자 삭제 요청건 안내 — 확인 시 표준코드 삭제 승인 화면(ULDINS11000) 팝업 호출(AS-IS $c.cm.alertRequiredDelByWeb 대체)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertRequiredDelByWeb = async function () {
    let msg = "[ 신청자 삭제 요청건 ]";
    msg += "\n - 본 코드는 신청자로부터(isin.krx.co.kr) 삭제요청이 들어온 상태입니다.";
    msg += "\n - 신청자요청 종목을 삭제하려면,[ 유가증권관리 > 표준코드삭제요청조회및승인 ]화면에서 삭제해야 합니다.";
    msg += "\n\n해당화면( 표준코드삭제요청조회및승인 )으로 이동하시겠습니까?";
    if (!(await $c.win.confirm(msg))) return;

    const options = {
        id : "ULDINS11000",
        popupName : "표준코드 삭제 승인",
        width : 1300,
        height : 780
    };
    await $c.win.openPopup("/ui/rcpt/ULDINS11000.xml", options, {});
};

/**
 * @method
 * @name checkFromTo
 * @description 조회 기간(시작일·종료일) 선후 검사 — 둘 다 입력된 상태에서 시작일이 종료일보다 크면 안내 후 시작일로 포커스
 * @param {*} startCal 시작일 inputCalendar
 * @param {*} endCal 종료일 inputCalendar
 * @param {String} label 기간 항목명
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkFromTo = async function (startCal, endCal, label) {
    const startDd = startCal.getValue();
    const endDd = endCal.getValue();
    if (!$c.util.isEmpty(startDd) && !$c.util.isEmpty(endDd) && startDd > endDd) {
        await $c.win.alert(label + " 시작일은 종료일보다 클 수 없습니다.");
        startCal.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name delSpecialChar
 * @description 입력값에서 특수문자를 제거한다(AS-IS $c.cm.delChar 대체)
 * @param {Object} comp 입력 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.delSpecialChar = function (comp) {
    const limitChar = /[~!@#$%^&*\\=+|:;?"<,.>/`()_']/g;
    const value = comp.getValue();
    if (limitChar.test(value)) {
        comp.setValue(value.replace(limitChar, ""));
    }
};

/**
 * @method
 * @name delSpecialCharPartial
 * @description 입력값에서 ~ # & ' 문자를 제거한다(AS-IS $c.cm.delChar3 대체)
 * @param {Object} comp 입력 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.delSpecialCharPartial = function (comp) {
    const limitChar = /[~#&']/g;
    const value = comp.getValue();
    if (limitChar.test(value)) {
        comp.setValue(value.replace(limitChar, ""));
    }
};

/**
 * @method
 * @name delNonNumeric
 * @description 입력값에서 숫자·소수점 외 문자를 제거한다(AS-IS $c.cm.delPoint 대체 — 원본 미반입, 동작 추정)
 * @param {Object} comp 입력 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.delNonNumeric = function (comp) {
    const value = comp.getValue();
    const cleaned = value.replace(/[^0-9.]/g, "");
    if (cleaned !== value) {
        comp.setValue(cleaned);
    }
};
